import{_ as e,o as a,c as r,a4 as o}from"./chunks/framework.BBs01uty.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/objects.md","filePath":"books/objects.md"}'),l={name:"books/objects.md"};function i(n,t,d,s,b,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h2 id="对象" tabindex="-1">对象 <a class="header-anchor" href="#对象" aria-label="Permalink to &quot;对象&quot;">​</a></h2><h4 id="类型" tabindex="-1">类型 <a class="header-anchor" href="#类型" aria-label="Permalink to &quot;类型&quot;">​</a></h4><p>string、number、undefined、boolean、null、symbol、object</p><p>其中object就是对象，是一种复杂基本类型</p><h4 id="对象的子类型-数组和函数" tabindex="-1">对象的子类型：数组和函数 <a class="header-anchor" href="#对象的子类型-数组和函数" aria-label="Permalink to &quot;对象的子类型：数组和函数&quot;">​</a></h4><h4 id="对象组成" tabindex="-1">对象组成 <a class="header-anchor" href="#对象组成" aria-label="Permalink to &quot;对象组成&quot;">​</a></h4><ol><li>对象由键值对组成，属性名永远是字符串(数组下标除外，是大于-1的整数)</li><li>es6新增可计算的属性名，中括号[]和变量组成，如[prefix + &#39;bar&#39;]</li><li>属性值可以是一个函数或者非函数</li></ol><p>注意：当属性值为一个函数的时候，函数和对象仍然只是间接关系，只是将函数的this动态绑定到对象上而已，并不能称之为&quot;方法&quot;</p><h4 id="对象的复制-浅复制和深复制" tabindex="-1">对象的复制：浅复制和深复制 <a class="header-anchor" href="#对象的复制-浅复制和深复制" aria-label="Permalink to &quot;对象的复制：浅复制和深复制&quot;">​</a></h4><p>浅复制：复制对象的引用</p><p>深复制：递归遍历对象所有简单基本类型的属性，并复制它们</p><p>相关方法：Object.assign、JSON序列化、递归遍历...</p><h4 id="属性描述符-数据描述符" tabindex="-1">属性描述符(数据描述符) <a class="header-anchor" href="#属性描述符-数据描述符" aria-label="Permalink to &quot;属性描述符(数据描述符)&quot;">​</a></h4><p>value：any 属性的值</p><p>writable：boolean 是否可写</p><p>enumberable：boolean 是否可枚举(for...in操作无法遍历到) propertyIsEnumberable()进行判断</p><p>configurable：boolean 是否可配置(此操作不可逆，一旦设置为false将无法再设置回true，例外=&gt;writable可由false设置为true ；无法修改可删除属性)</p><h4 id="不可变" tabindex="-1">不可变 <a class="header-anchor" href="#不可变" aria-label="Permalink to &quot;不可变&quot;">​</a></h4><ol><li>对象常量：writable和configurable都设置为false</li><li>禁止扩展：Object.preventExtentions()</li><li>密封：Object.seal() 实际上调用Object.preventExtentions()以及将configurable设置false</li><li>冻结：Object.freeze() 实际上调用Object.seal()以及设置writable为false</li></ol><h4 id="get-和-put-操作" tabindex="-1">[[Get]]和[[Put]]操作 <a class="header-anchor" href="#get-和-put-操作" aria-label="Permalink to &quot;[[Get]]和[[Put]]操作&quot;">​</a></h4><p>[[Get]]：语言规范中，myObject.a实际上是实现了[[Get]]操作，该操作会在该对象查找是否有a属性，若未找到则遍历整个原型链，若仍然未找到则返回undefined，获取属性的值时会先检查访问描述符getter是否存在，存在则调用getter，否则直接返回属性的值</p><p>[[Put]]：属性赋值操作，大致会检查如下内容：</p><ol><li>检查属性是否是访问描述符，若是且存在setter，则调用setter</li><li>属性的描述符中writable是否为false，若是则在非严格模式下静默赋值失败，严格模式抛出TypeError错误</li><li>如果都不是，正常赋值</li></ol><h4 id="getter-setter-访问描述符" tabindex="-1">Getter&amp;Setter(访问描述符) <a class="header-anchor" href="#getter-setter-访问描述符" aria-label="Permalink to &quot;Getter&amp;Setter(访问描述符)&quot;">​</a></h4><p>当属性被定义getter、setter或者二者都有时，这个属性被定义为&quot;访问描述符&quot;，相对&quot;数据描述符&quot;，此时javascript会忽略value和writable，只关心get和set</p><h4 id="存在性以及遍历" tabindex="-1">存在性以及遍历 <a class="header-anchor" href="#存在性以及遍历" aria-label="Permalink to &quot;存在性以及遍历&quot;">​</a></h4><p>in：in操作符会检查对象本身以及原型链的属性</p><p>hasOwnProperty：只会检查对象本身(使用时，考虑到hasOwnProperty是prototype属性，而通过Object.create(null)创建的对象无prototype，所以建议这样使用：Object.prototype.hasOwnProperty.call(myObject,[property]))</p><table tabindex="0"><thead><tr><th></th><th>是否查找原型链</th></tr></thead><tbody><tr><td>in操作符</td><td>是</td></tr><tr><td>hasOwnProperty</td><td>否</td></tr><tr><td>Object.keys() &amp;&amp; for...in</td><td>否</td></tr></tbody></table><table tabindex="0"><thead><tr><th></th><th>是否只查找可枚举属性</th></tr></thead><tbody><tr><td>Object.keys()</td><td>是</td></tr><tr><td>getOwnPropertyNames()</td><td>否</td></tr><tr><td>for...in</td><td>是</td></tr></tbody></table><p>for...in：遍历对象无法直接获取属性值，需要手动获取</p><p>for...of：首先请求迭代器对象，自动遍历迭代器，数组有迭代器对象，对象没有，不过可以自定义</p>',32)])])}const u=e(l,[["render",i]]);export{c as __pageData,u as default};
